<x-layouts.admin><h1>{{ $article->exists ? 'ویرایش مقاله' : 'مقاله جدید' }}</h1><section class="form-card"><form method="post" action="{{ $article->exists ? route('admin.articles.update', $article) : route('admin.articles.store') }}">@csrf @if($article->exists)@method('PUT')@endif @foreach(['title'=>'عنوان','excerpt'=>'خلاصه','body'=>'متن'] as $field=>$label)<h2>{{ $label }}</h2><div class="form-grid">@foreach(['fa'=>'فارسی','en'=>'English','ar'=>'العربية'] as $locale=>$language)<label>{{ $language }}<textarea name="{{ $field }}_{{ $locale }}" rows="{{ $field === 'body' ? 6 : 3 }}" @required($field !== 'excerpt')>{{ old($field.'_'.$locale, $article->{$field}[$locale] ?? '') }}</textarea></label>@endforeach</div>@endforeach<div class="form-grid"><label>نامک<input name="slug" required value="{{ old('slug', $article->slug) }}"></label><label>تاریخ انتشار<input type="datetime-local" name="published_at" value="{{ old('published_at', $article->published_at?->format('Y-m-d\TH:i')) }}"></label></div><fieldset><legend>محصولات مرتبط</legend>@foreach($products as $product)<label class="check"><input type="checkbox" name="product_ids[]" value="{{ $product->id }}" @checked(in_array($product->id, old('product_ids', $article->products->pluck('id')->all())))> {{ $product->localized('title') }}</label>@endforeach</fieldset><label class="check"><input type="checkbox" name="is_published" value="1" @checked(old('is_published', $article->is_published ?? false))> منتشر شود</label><label class="check"><input type="checkbox" name="is_demo" value="1" @checked(old('is_demo', $article->is_demo ?? true))> محتوای دمو</label><button class="button">ذخیره مقاله</button></form></section></x-layouts.admin>
